1	// Glues CsrTrigger and StateDrain. The simulator's run-loop calls on_retire
2	// once per committed PC; the controller decides via the trigger map whether
3	// to drain state and returns the populated hybrid_state_v1 if so. The
4	// caller (simulator.hpp) is responsible for writing the file and exiting
5	// with EXIT_HANDOFF_TO_QEMU.
6	
7	#pragma once
8	
9	#include "hybrid/csr_trigger.hpp"
10	#include "hybrid/insn_match.h"
11	#include "hybrid/measure_start_snapshot.hpp"
12	#include "hybrid/resume_driver.hpp"
13	#include "hybrid/state_abi.h"
14	#include "hybrid/state_drain.hpp"
15	
16	#include <cstdint>
17	#include <functional>
18	#include <optional>
19	#include <stdexcept>
20	#include <utility>
21	
22	namespace hybrid
23	{
24	
25	template<typename Trigger, typename Observer = NullObserver>
26	class HandoffController
27	{
28	public:
29	  HandoffController(Trigger trigger, DmiBus& bus)
30	      : trigger_{std::move(trigger)}, drain_{bus}
31	  {}
32	
33	  HandoffController(Trigger trigger, DmiBus& bus, Observer observer)
34	      : trigger_{std::move(trigger)},
35	        drain_{bus},
36	        observer_{std::move(observer)}
37	  {}
38	
39	  // Snapshot of the QEMU 1 input state. When set, drain merges FP/CSR/V
40	  // fields from the snapshot into the freshly drained GPRs+PC, avoiding
41	  // a per-field DM Abstract Command on every handoff.
42	  void set_passthrough_input(hybrid_state_v1 input)
43	  {
44	    passthrough_ = input;
45	  }
46	
47	  // cosim_roi F2: every `interval` retires, drain a resumable checkpoint and
48	  // hand it to `sink` (k counts from 1). The caller writes the numbered file;
49	  // the hart keeps running. Requires the passthrough snapshot (checkpoints
50	  // reuse drain_checkpoint, which needs the QEMU1 flags/CSR slots).
51	  using CosimSink = std::function<void(const hybrid_state_v1&, uint64_t)>;
52	  void enable_cosim(uint64_t interval, CosimSink sink)
53	  {
54	    cosim_interval_ = interval;
55	    cosim_next_     = interval;
56	    cosim_sink_     = std::move(sink);
57	  }
58	
59	  // Read-only view of the underlying trigger. Used by the ROI kanata-gate
60	  // derivation, which needs to read scanned EXIT PCs without consuming them.
61	  auto trigger() const -> const Trigger& { return trigger_; }
62	
63	  // Read-only view of the observer slot. F16 (StateDrain) reads the warmup
64	  // snapshot from here when copying into the ABI struct.
65	  auto observer() const -> const Observer& { return observer_; }
66	  auto observer() -> Observer& { return observer_; }
67	
68	  auto on_retire(uint64_t pc) -> std::optional<hybrid_state_v1>
69	  {
70	    if constexpr (requires { trigger_.observe_commit(); }) {
71	      trigger_.observe_commit();
72	    }
73	    if constexpr (requires { observer_.observe_commit(); }) {
74	      observer_.observe_commit();
75	    }
76	    const auto hit = trigger_.lookup(pc);
77	    // Only EXIT drains; entry is QEMU's job, vsim ignores ENTER. Every
78	    // non-exit retire advances the cosim checkpoint counter instead.
79	    if (!hit || hit->kind != HYBRID_HANDOFF_EXIT) {
80	      maybe_cosim_checkpoint();
81	      return std::nullopt;
82	    }
83	    push_warmup_snapshot();
84	    if (passthrough_) return drain_.drain_with_passthrough(*passthrough_);
85	    return drain_.drain();
86	  }
87	
88	private:
89	  // F16: push warmup snapshot into the drain right before it runs so the
90	  // returned state carries mcycle_at_measure_start / minstret_at_measure_start.
91	  // The if-constexpr branch compiles away for NullObserver (no accessors).
92	  void push_warmup_snapshot()
93	  {
94	    if constexpr (requires { observer_.mcycle_at_measure_start(); }) {
95	      drain_.set_warmup_snapshot(observer_.mcycle_at_measure_start(),
96	                                 observer_.minstret_at_measure_start());
97	    }
98	  }
99	
100	  // Monotonic target (not modulo) so the slack retires that commit while a
101	  // checkpoint's haltreq propagates are simply absorbed into the next window.
102	  void maybe_cosim_checkpoint()
103	  {
104	    if (cosim_interval_ == 0) return;
105	    if (++cosim_retires_ < cosim_next_) return;
106	    cosim_next_ += cosim_interval_;
107	    if (!passthrough_)
108	      throw std::runtime_error(
109	        "HandoffController cosim: checkpoints require the QEMU passthrough "
110	        "snapshot (set_passthrough_input)");
111	    push_warmup_snapshot();
112	    cosim_sink_(drain_.drain_checkpoint(*passthrough_), ++cosim_count_);
113	  }
114	
115	  Trigger trigger_;
116	  StateDrain drain_;
117	  Observer observer_{};
118	  std::optional<hybrid_state_v1> passthrough_;
119	  uint64_t cosim_interval_ = 0;  // 0 = cosim disabled
120	  uint64_t cosim_retires_  = 0;
