// two modes are mutually exclusive on a single run -- callers pass at most
// one. Multi-hart out of scope per F6: the trigger counts hart-0 retires.
void enable_hybrid_icount_handoff(const std::string& state_out_path,
                                  uint64_t icount_target,
                                  uint64_t vsim_warmup_icount = 0)
{
  hybrid::IcountTrigger trigger{icount_target};
  spdlog::info("hybrid: icount-trigger mode, target={}", icount_target);

  auto snapshot = make_handoff_snapshot(vsim_warmup_icount);
  hybrid_icount_handoff_.emplace(std::move(trigger), *hybrid_dmi_bus_,
                                 std::move(snapshot));
  if (hybrid_input_state_)
    hybrid_icount_handoff_->set_passthrough_input(*hybrid_input_state_);
  hybrid_state_path_ = state_out_path;
}

// cosim_roi F2: drain a resumable checkpoint every `interval` retires and
// write it to `<handoff_out>.ckpt<k>` (k from 1); the hart keeps running.
// Call AFTER enable_hybrid_handoff -- checkpoints ride the CSR/PC handoff
// controller, so icount mode cannot carry them.
void enable_hybrid_cosim(uint64_t interval)
{
  if (!hybrid_handoff_)
    throw std::runtime_error(
      "enable_hybrid_cosim: requires the CSR/PC hybrid handoff "
      "(incompatible with --hybrid-icount)");
  spdlog::info("hybrid cosim: checkpoint every {} retires", interval);
  hybrid_handoff_->enable_cosim(
    interval, [this](const hybrid_state_v1& drained, uint64_t k) {
      auto state = drained;
      // Same V-register merge as the exit drain: the checkpoint's vse8.v
      // sweep parked v0..v31 in scratch RAM; lift the bytes into vreg[].
      if ((state.flags & HYBRID_FLAG_V) != 0u) {
        hybrid::read_v_from_scratch(
          state,
          std::span<const uint8_t>{platform.main_memory.data.data(),
                                   platform.main_memory.data.size()},
          platform.main_memory.region.base_address);
      }
      const auto path = hybrid_state_path_ + ".ckpt" + std::to_string(k);
      spdlog::info("hybrid cosim: checkpoint {} at pc=0x{:x}, writing {}",
                   k, state.pc, path);
      std::ofstream f(path, std::ios::binary);
      f.write(reinterpret_cast<const char*>(&state), sizeof(state));
    });
}

void restore_context(const std::string& dir)
{
  context_config.dir = dir;
  context_config.restore(platform, cpu);
}

void save_context(const std::string& dir)
{
  context_config.dir = dir;
  context_config.save(platform, cpu);
}

// skip_memory_load: parse the ELF and set the reset vector, but leave
// platform.main_memory untouched. Used in tier-2 hybrid resume where
// QEMU 1's -kernel already populated the shared mmap; re-loading would
// zero-fill the .bss tail of each PT_LOAD and destroy phase-1 writes
// to static buffers. The reset vector is still set so the hart has a
// valid fetch target during the post-reset cycles that precede the DMI
// halt+DPC-write resume sequence.
void load_elf(const std::string& path, bool skip_memory_load = false)
{
  const auto elf = LIEF::ELF::Parser::parse(path);
  if (!elf) {
    spdlog::critical("Check if it's a valid ELF file path : {}", path);
    exit(1);
  }

  if (!skip_memory_load)
    read_elf_into_memory(
      *elf,
      static_cast<xlen_t>(platform.main_memory.region.base_address),
      platform.main_memory.data);

